import sys, os

if "src" not in sys.path:
    sys.path.insert(0, "src")

def main():
    # Imports that the runtime cannot satisfy are attempted; if they fail
    # we fall back to a minimal local implementation of `lypning` so the
    # program is still correct on CPython.
    try:
        from lypning import conformance as cf
        from lypning.corpus import Entry
    except Exception:
        import re as _re
        class _Entry:
            __slots__ = ("id", "program")
            def __init__(self, id, program):
                self.id = id
                self.program = program
            def __repr__(self):
                return f"Entry({self.id!r}, {self.program!r})"
        class _ConformanceModule:
            _IMPORTS_RANDOM = _re.compile(r"\bimport\s+random\b|\bfrom\s+random\b")
            @staticmethod
            def is_seeded_stream(e):
                p = e.program
                return _re.search(r"\brandom\.seed\s*\(", p) is not None
        cf = _ConformanceModule()
        Entry = _Entry

    n = 0
    seeded = 0
    sus = []

    for root, dirs, files in os.walk("tests/corpus"):
        for fn in sorted(files):
            if not fn.endswith(".jsonl"):
                continue
            path = os.path.join(root, fn)
            with open(path) as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        o = json.loads(line)
                    except Exception:
                        continue
                    p = o.get("program", "")
                    if not isinstance(p, str):
                        continue
                    if not cf._IMPORTS_RANDOM.search(p):
                        continue
                    n += 1
                    e = Entry(id=o.get("id", "x"), program=p)
                    if cf.is_seeded_stream(e):
                        seeded += 1
                        if (re.search(r"seed\s*\(\s*(\)|None|[a-zA-Z_]\w*\s*\))", p)
                                or "def seed" in p
                                or re.search(r"seed\(\)", p)):
                            sus.append((path, p[:200]))

    print("random programs:", n, "seeded:", seeded)
    for f, p in sus:
        print("SUSPECT", f, repr(p))

if __name__ == "__main__":
    main()

