# Reproduce glob.glob("tests/corpus/**/*.jsonl", recursive=True) using os.walk.
def find_jsonl(base):
    out=[]
    for dirpath,dirnames,filenames in os.walk(base):
        # prune directories containing a dot component (glob skips hidden dirs)
        rel=os.path.relpath(dirpath,base)
        if rel!=os.curdir:
            parts=rel.split(os.sep)
            if any(p.startswith(".") for p in parts):
                dirnames[:]=[]
                continue
        else:
            pass
        # also skip immediate components with leading dot in the walked tree
        new=[]
        for d in dirnames:
            if d.startswith("."):
                continue
            new.append(d)
        dirnames[:]=new
        for fn in filenames:
            if not fn.endswith(".jsonl"):
                continue
            full=os.path.join(dirpath,fn)
            out.append(full)
    return out

