import json, re, sys, os
sys.path.insert(0, "src")
from lypning import conformance as cf
from lypning.corpus import Entry


def list_files(base_dir):
    out = []
    if not os.path.isdir(base_dir):
        return out

    def walk(d):
        try:
            names = os.listdir(d)
        except OSError:
            return
        for n in sorted(names):
            p = os.path.join(d, n)
            if os.path.isdir(p):
                walk(p)
            elif os.path.isfile(p) and n.endswith(".jsonl"):
                out.append(p)

    walk(base_dir)
    return out


def main():
    n = 0
    seeded = 0
    sus = []
    files = list_files("tests/corpus")
    # Mimic glob("tests/corpus/**/*.jsonl", recursive=True) relative-path form
    for f in files:
        relf = f[len("tests/corpus/"):] if f.startswith("tests/corpus/") else f
        try:
            fh = open(f)
        except OSError:
            continue
        lines = []
        with fh:
            for line in fh:
                lines.append(line)
        del fh
        for raw_line in lines:
            line = raw_line.strip()
            if not line:
                continue
            o = json.loads(line)
            p = o.get("program", "")
            if not cf._IMPORTS_RANDOM.search(p):
                continue
            n += 1
            e = Entry(id=o.get("id", "x"), program=p)
            if cf.is_seeded_stream(e):
                seeded += 1
                m1 = re.search(r"seed\s*\(\s*(\)|None|[a-zA-Z_]\w*\s*\))", p)
                m2 = re.search(r"seed\(\)", p)
                if m1 or "def seed" in p or m2:
                    sus.append((relf, p[:200]))
    print("random programs:", n, "seeded:", seeded)
    for f, p in sus:
        print("SUSPECT", f, repr(p))


if __name__ == "__main__":
    main()

