def _make_engine(program, tags=()):
    return (program, tuple(tags))

def mk(out, rc=0):
    return eng.Result("cpython", "python3", rc, out, "", 1000)

def _E(p, tags=()):
    class E:
        def __init__(self, _p, _tags=()):
            self.program = _p
            self.tags = _tags
    return E(p, tags)

for name, p in [("comma-import unseeded", "import os, random\nprint(random.random())"),
                ("plain unseeded", "import random\nprint(random.random())"),
                ("seed in comment", "import random  # random.seed(1)\nprint(random.random())")]:
    v = c.classify(mk("0.1\n"), mk("0.2\n"), "cpython", _E(p))
    print(f"{name:28s} ->", v)

