def word_chars(c):
    if 'a' <= c <= 'z':
        return True
    if 'A' <= c <= 'Z':
        return True
    if '0' <= c <= '9':
        return True
    if c == '_':
        return True
    # match \w (no UNICODE flag); only ASCII considered
    if ord(c) < 128:
        return False
    # non-ASCII: Python default re treats letters/digits as \w; approximate by isalnum-like via str methods? Avoid.
    # To be safe, use str.isalpha/isdecimal on single char as fallback for unicode \w.
    o = ord(c)
    if (o >= 0x0041 and o <= 0x005A) or (o >= 0x0061 and o <= 0x007A) or (o >= 0x0030 and o <= 0x0039):
        return True
    # use str category-ish: accept alnum (unicode) and underscore; ignore other connectors.
    ch = c
    if ch.isdigit() or ch.isalpha():
        return True
    return False


def search(pattern_kind, s):
    """Return bool matching the specific regexes used, without lookbehind."""
    n = len(s)

    if pattern_kind == 'dotted_seed':
        return "random.seed" in s

    if pattern_kind == 'import_random_as':
        # r'\bimport\s+random\s+as\s+\w'
        i = 0
        while i < n:
            if s[i] == 'i':
                j = i
                if s.startswith('import', i):
                    end = i + 6
                    k = end
                    ws = 0
                    while k < n and (s[k] == ' ' or s[k] == '\t'):
                        k += 1
                        ws += 1
                    if ws > 0:
                        if s.startswith('random', k):
                            kk = k + 6
