                i += 1
                continue
            # try to match import
            rest = s[i:]
            if rest.startswith('import'):
                j = i + 6
                # check boundary after import
                if j < n and (s[j].isalnum() or s[j] == '_'):
                    i += 1
                    continue
                # \s+ 
                k = j
                while k < n and s[k] in ' \t\n\r\f\v':
                    k += 1
                if k == j:
                    i += 1
                    continue
                # literal "random"
                if s[k:k+6] != 'random':
                    i += 1
                    continue
                m = k + 6
                # check boundary after random
                if m < n and (s[m].isalnum() or s[m] == '_'):
                    i += 1
                    continue
                # \s+ as
                p = m
                while p < n and s[p] in ' \t\n\r\f\v':
                    p += 1
                if p == m:
                    i += 1
                    continue
                if s[p:p+2] != 'as':
                    i += 1
                    continue
                q = p + 2
                # check boundary after as
                if q < n and (s[q].isalnum() or s[q] == '_'):
                    i += 1
                    continue
                # \s+
                r = q
                while r < n and s[r] in ' \t\n\r\f\v':
                    r += 1
                if r == q:
                    i += 1
                    continue
                # \w
                if r < n and (s[r].isalnum() or s[r] == '_'):
                    return True
                else:
                    i += 1
                    continue
            else:
                i += 1
        else:
            i += 1
    return False


