            fs += '0'
        fs += str(width)
    if prec is not None:
        fs += '.' + str(prec)
    fs += spec if spec != '' else 'g'
    try:
        r = format(f, fs)
    except (ValueError, TypeError) as e:
        return ('__error__', type(e).__name__, str(e))
    return ('ok', '', r)

