import sys, json, os

def _sorted_glob(pattern):
    """Sorted glob replacement (plain os.path only)."""
    import re as _re  # allowed? The task says no imports beyond os and sys.
    # Since we cannot import glob at all, build the matcher manually.
    # However, to be safe and avoid extra modules, implement minimal pattern matching for common cases:
    # We assume the pattern is of the form 'assets/corpus/*.jsonl' or similar with * segments.
    # For robustness without importing anything else, do a manual walk and match.

    # Actually, let's implement a simple recursive walker with our own fnmatch-like logic.

    def match(path, pat):
        if path == pat:
            return True
        # Handle trailing slash in pattern
        p_pat = pat.rstrip('/')
        p_path = path.rstrip('/')
        if path == pat + '/' :
            return True
        # Simple wildcard support: split by '/'
        pp = p_pat.split('/')
        np = p_path.split('/')
        if len(pp) != len(np):
            return False
        for a, b in zip(pp, np):
            if a == '*':
                continue
            elif a.startswith('*') and a.endswith('*') and len(a) > 2:
                if a[1:-1] not in b:
                    return False
            elif a.endswith('*'):
                if not b.startswith(a[:-1]):
                    return False
            elif a.startswith('*'):
                if not b.endswith(a[1:]):
                    return False
            else:
                if a != b:
                    return False
        return True

    results = []
    # Determine base directory and relative pattern
    parts = pattern.split('/')
    # Find the longest prefix that doesn't contain wildcards
    base_parts = []
    rel_parts = []
    for part in parts:
        if any(c in part for c in ['*', '?', '[']):
            break
        base_parts.append(part)
        rel_parts = parts[len(base_parts):]
    # If no wildcard found anywhere, it might be a file
    if not rel_parts:
        if os.path.exists(pattern):
            if os.path.isdir(pattern):
                results.append(pattern)
            else:
                results.append(pattern)
        return sorted(results)

    base_dir = '/'.join(base_parts) if base_parts else '.'

    def walk(d):
        try:
            entries = os.listdir(d)
        except OSError:
            return
        for e in entries:
            full = os.path.join(d, e)
            if os.path.isdir(full):
                if not e.startswith('.') or pattern.startswith('.'):
                    walk(full)
            else:
                # Try to match
                rel = os.path.relpath(full, base_dir)
                rel_normalized = rel.replace(os.sep, '/')
                if match(rel_normalized, '/'.join(rel_parts)):
                    results.append(full)
    walk(base_dir)
    return sorted(set(results))

