class _ExprEval:
    def eval(self, src):
        return self._run(eval(compile(src, '<expr>', 'eval')))

    def _run(self, node):
        import ast
        try:
            return self._eval(node)
        except BaseException as e:
            # preserve exact original message and type; the compile/eval of a literal expr string will
            # raise identical exception to plain eval(expr)
            if isinstance(e, SyntaxError):
                raise
            raise

    def _eval(self, node):
        t = type(node).__name__
        if t == "Expression":
            return self._eval(node.body)
        if t == "Name":
            if node.id in self._g:
                return self._g[node.id]
            raise NameError(name=node.id)
        if t == "Constant":
            return node.value
        if t == "Attribute":
            obj = self._eval(node.value)
            for n in node.attrs:
                obj = getattr(obj, n)
            return obj
        if t == "Call":
            func = self._eval(node.func)
            args = [self._eval(a) for a in node.args]
            kw = {k.arg: self._eval(v) for k, v in zip(node.keywords, node.keywords)}
            return func(*args, **kw)
        if t == "Keyword":
            pass
        if t == "Str":
            return node.s
        if t == "Num":
            return node.n
        if t == "Tuple":
            return tuple(self._eval(e) for e in node.elts)
        if t == "List":
            return [self._eval(e) for e in node.elts]
        if t == "Dict":
            d = {}
            for k, v in zip(node.keys, node.values):
                kk = self._eval(k) if k is not None else None
                vv = self._eval(v)
                d[kk] = vv
            return d
        if t == "BinOp":
            l = self._eval(node.left); r = self._eval(node.right); o = type(node.op).__name__
            if o == "Add": return l + r
            if o == "Sub": return l - r
            if o == "Mult": return l * r
            if o == "Div": return l / r
            if o == "Mod": return l % r
            if o == "Pow": return l ** r
            if o == "FloorDiv": return l // r
            if o == "LShift": return l << r
            if o == "RShift": return l >> r
            if o == "BitOr": return l | r
            if o == "BitAnd": return l & r
            if o == "BitXor": return l ^ r
        if t == "UnaryOp":
            x = self._eval(node.operand); o = type(node.op).__name__
            if o == "USub": return -x
            if o == "UAdd": return +x
            if o == "Not": return not x
            if o == "Invert": return ~x
        if t == "BoolOp":
            o = type(node.op).__name__
            vals = [self._eval(v) for v in node.values]
            if o == "And":
                for v in vals:
                    if not v: return v
                return vals[-1]
            if o == "Or":
                for v in vals:
                    if v: return v
                return vals[0]
        if t == "Compare":
            left = self._eval(node.left)
            res = True
            for op, cmp in zip(node.ops, node.comparators):
                right = self._eval(cmp)
                on = type(op).__name__
                if on == "Eq": ok = (left == right)
                elif on == "NotEq": ok = (left != right)
                elif on == "Lt": ok = (left < right)
                elif on == "LtE": ok = (left <= right)
                elif on == "Gt": ok = (left > right)
                elif on == "GtE": ok = (left >= right)
                elif on == "Is": ok = (left is right)
                elif on == "IsNot": ok = (left is not right)
                elif on == "In": ok = (left in right)
                elif on == "NotIn": ok = (left not in right)
                else: raise NotImplementedError(on)
                if not ok:
                    res = False
                    break
                left = right
            return res
        if t == "IfExp":
            c = self._eval(node.test)
            return self._eval(node.body) if c else self._eval(node.orelse)
        if t == "Subscript":
            val = self._eval(node.value)
            idx = node.slice
            if type(idx).__name__ == "Index":
                key = self._eval(idx.value)
            else:
                key = idx
            return val[key]
        if t == "Slice":
            lower = self._eval(node.lower) if node.lower is not None else None
            upper = self._eval(node.upper) if node.upper is not None else None
            step = self._eval(node.step) if node.step is not None else None
            return slice(lower, upper, step)
        raise ValueError("unsupported node: " + t)


