def fmt_d(width, zero, v):
    s = str(v) if not isinstance(v, bool) else ('1' if v else '0')
    if width:
        if zero:
            sign = ''
            neg = False
            if v is True or (v == 1 and not isinstance(v, int)) :
                pass
            # handle negative numbers
            if (v < 0 if isinstance(v, int) else False):
                neg = True
                ss = s[1:]
                padded = ss.zfill(width - 1)
                s = '-' + padded
            else:
                s = s.zfill(width)
        else:
            if (isinstance(v, int) and v < 0) or (isinstance(v, float) and v < 0):
                s = s.rjust(width)
            else:
                s = s.rjust(width)
    return s


