# Now handle the %b case by formatting manually
# The last original entry was %.4b for each of (5,-5,0,True,False)
# We need to produce byte-identical output for those.

def bin_repr(n, signed=False):
    """Return binary string representation like Python's %b"""
    if n >= 0:
        bits = ''
        if n == 0:
            bits = '0'
        else:
            while n > 0:
                bits = ('1' if n & 1 else '0') + bits
                n >>= 1
        return bits
    else:
        # negative: Python uses two's complement? No, %b just prepends '-'
        return '-' + bin_repr(-n)


