                sign = '-'
                abs_iv = -iv
            else:
                sign = ''
                if has_flag('+'):
                    sign = '+'
                abs_iv = iv
            hex_digits = ''
            tmp = abs_iv
            if tmp == 0:
                hex_digits = '0'
            else:
                while tmp > 0:
                    hex_digits = hexchars[tmp % 16] + hex_digits
                    tmp //= 16
            if has_flag('#') and abs_iv != 0:
                prefix = '0x' if conv == 'x' else '0X'
                hex_digits = prefix + hex_digits
