        if upper:
            hs = "0123456789ABCDEF"
        else:
            hs = "0123456789abcdef"
        if n == 0:
            return "0"
        digs = []
        nn = abs(n)
        while nn:
            digs.append(hs[nn & 0xF])
            nn >>= 4
        digs.reverse()
        prefix = "-" if n < 0 else ""
        return prefix + "".join(digs)

    def oct_digits(n):
        nn = abs(n)
        if nn == 0:
            s = "0"
        else:
            digs = []
            while nn:
                digs.append(str(nn & 0o7))
                nn >>= 3
            digs.reverse()
            s = "".join(digs)
        return ("-" if n < 0 else "") + s

    def bin_digits(n):
        nn = abs(n)
        if nn == 0:
            s = "0"
        else:
            digs = []
            while nn:
                digs.append(str(nn & 1))
                nn >>= 1
            digs.reverse()
            s = "".join(digs)
        return ("-" if n < 0 else "") + s

