        total = width
        if total > len(result):
            pad = total - len(result)
            if '0' in flags:
                # Zero padding after sign/prefix
                if result.startswith('-'):
                    result = '-' + '0'*pad + result[1:]
                else:
                    result = '0'*pad + result
            else:
                if '+' in flags or value >= 0:
                    if '-' in flags:
                        result = ' ' * pad + result
                    else:
                        result = ' ' * pad + result
                else:
                    if '-' in flags:
                        result = result.ljust(total)
                    else:
                        result = result.rjust(total)

