import os, sys

def _walk(dirpath):
    names = []
    try:
        entries = os.listdir(dirpath)
    except OSError:
        return names
    for name in entries:
        fullpath = os.path.join(dirpath, name)
        if os.path.isfile(fullpath):
            names.append(name)
        elif os.path.isdir(fullpath):
            if name != "." and name != "..":
                subnames = _walk(fullpath)
                names.extend(subnames)
    return names

results = {}
try:
    cwd_names = sorted(os.listdir("."))
except OSError:
    cwd_names = []

for entry in cwd_names:
    if entry == "." or entry == "..":
        continue
    fullpath = os.path.join(".", entry)
    exts = entry.split(".")
    has_py = len(exts) > 1 and exts[-1] == "py"
    if os.path.isfile(fullpath) and has_py:
        results[entry] = True
    elif os.path.isdir(fullpath):
        for fname in sorted(_walk(fullpath)):
            fexts = fname.split(".")
            fhas_py = len(fexts) > 1 and fexts[-1] == "py"
            if fhas_py:
                results[fname] = True

if not results:
    print("[]")
else:
    sorted_keys = sorted(results.keys())
    print("[" + ", ".join(repr(k) for k in sorted_keys) + "]")

