import sys

def find_cpython():
    import shutil
    return shutil.which('python3') or shutil.which('python')

def reference_python_env():
    import os
    env = dict(os.environ)
    return {k: v for k, v in sorted(env.items()) if 'PYTHON' in k}

print('harness', sys.version_info[:2], 'find_cpython', find_cpython(), 'env', reference_python_env())

